  static bool HasOwnedDialog(Window settings){foreach(Window child in settings.OwnedWindows)if(child.IsVisible)return true;return false;}
  static bool SettingsOwnsWindow(IntPtr window,IntPtr settings){for(int depth=0;window!=IntPtr.Zero&&depth<16;depth++,window=DesktopNative.GetWindow(window,4))if(window==settings||DesktopNative.IsChild(settings,window))return true;return false;}
  static TextBlock SettingsText(string value,int size=12){return new TextBlock{Text=value,FontSize=size,Foreground=Color("#BDC5D3"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,8)};}
  static CheckBox SettingCheck(StackPanel panel,string label,bool value){var check=new CheckBox{Content=new TextBlock{Text=label,TextWrapping=TextWrapping.Wrap},IsChecked=value,Margin=new Thickness(0,10,0,5)};System.Windows.Automation.AutomationProperties.SetName(check,label);panel.Children.Add(check);return check;}
  static ComboBox SettingChoice(StackPanel panel,string label,string[] values,int index){panel.Children.Add(SettingsText(label));var combo=new ComboBox{Margin=new Thickness(0,0,0,12),HorizontalAlignment=HorizontalAlignment.Stretch};foreach(string value in values)combo.Items.Add(value);combo.SelectedIndex=Math.Max(0,index);System.Windows.Automation.AutomationProperties.SetName(combo,label);panel.Children.Add(combo);return combo;}
  static TextBox SettingInput(StackPanel panel,string label,string value){panel.Children.Add(SettingsText(label));var input=new TextBox{Text=value,Margin=new Thickness(0,0,0,8),MinWidth=70};System.Windows.Automation.AutomationProperties.SetName(input,label);panel.Children.Add(input);return input;}
  static void SectionHeading(StackPanel panel,string text){var heading=SettingsText(text,15);heading.Foreground=Color("#F1F2F5");heading.FontWeight=FontWeights.SemiBold;heading.Margin=new Thickness(0,5,0,8);panel.Children.Add(heading);}
  static StackPanel SettingsTab(TabControl tabs,string title){var panel=new StackPanel{Margin=new Thickness(0,0,14,8)};var scroll=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Focusable=true};tabs.Items.Add(new TabItem{Header=title,Content=scroll});return panel;}
